## Contract (agreed 2026-10-14; frozen for wave 2: a needed change is a new layer on types.py, never an edit inside a wave-2 sprint)
```python
# result.py
@dataclass(frozen=True)
class Ok(Generic[T]): value: T
@dataclass(frozen=True)
class Err: error: "Error"
Result = Ok[T] | Err

@dataclass(frozen=True)
class CommandFailed: kind: Literal["command_failed"]; argv: tuple[str, ...]; code: int; stderr: str; fix: str
@dataclass(frozen=True)
class Timeout: kind: Literal["timeout"]; argv: tuple[str, ...]; seconds: int; fix: str
@dataclass(frozen=True)
class Rejected: kind: Literal["rejected"]; argv: tuple[str, ...]; status: int; message: str; fix: str   # e.g. GitHub 401/403
@dataclass(frozen=True)
class Unreachable: kind: Literal["unreachable"]; argv: tuple[str, ...]; message: str; fix: str
@dataclass(frozen=True)
class ParseFailed: kind: Literal["parse_failed"]; source: str; message: str; fix: str
@dataclass(frozen=True)
class NotFound: kind: Literal["not_found"]; what: str; fix: str
@dataclass(frozen=True)
class ConfigInvalid: kind: Literal["config_invalid"]; key: str; value: str; fix: str
@dataclass(frozen=True)
class LockHeld: kind: Literal["lock_held"]; snapshot_age_s: int | None; fix: str   # None: no snapshot yet
@dataclass(frozen=True)
class IoFailed: kind: Literal["io_failed"]; path: str; message: str; fix: str      # a state/snapshot write or read failed
Error = CommandFailed | Timeout | Rejected | Unreachable | ParseFailed | NotFound | ConfigInvalid | LockHeld | IoFailed   # discriminated by `kind`; every variant carries `fix` (the next action)

# types.py -- source types: each source module returns these, never raw strings of its tool
Presence = Literal["active", "idle", "offline", "blocked", "unknown"]
@dataclass(frozen=True)
class Member: name: str; presence: Presence; presence_since: datetime   # recipients come from RepoConfig and --as, never from the roster
@dataclass(frozen=True)
class Task: id: str; agent: str; state: Literal["assigned", "active"]; position: int; assigned_at: datetime; state_since: datetime; description: str   # state_since = atm `updated_at` (atm reports no started_at)
@dataclass(frozen=True)
class Bead: id: str; title: str; status: Literal["open", "in_progress", "blocked", "closed"]; labels: tuple[str, ...]; parent: str | None
    blocked_by: tuple[str, ...]; assignee: str | None; metadata: Mapping[str, Any]; created_at: datetime; claimed_at: datetime | None; closed_at: datetime | None
StepKind = Literal["dev", "fix", "sanity", "qa", "finding", "plan_review", "container", "other"]
@dataclass(frozen=True)
class Step: bead_id: str; sprint: str | None; kind: StepKind; quick_fix: bool; anchor: bool; status: Literal["open", "in_progress", "blocked", "closed"]
    ready: bool; assignee: str | None; branch: str | None; target: str | None; worktree: str | None; layer: int | None
    difficulty: Literal["hard", "normal", "fast"] | None; tag: str; top_epic: str | None; claimed_at: datetime | None; closed_at: datetime | None; title: str
    checked_bead: str | None; sprint_bead: str | None; qa_round: int | None; carry_forward: str | None
    # production keys (formulas sprint-group/finding-group, qa-bead.json.j2, finding-bead.json.j2):
    # sanity: checked_bead = metadata.dev_bead
    # QA: checked_bead = metadata.checked_bead; qa_round = metadata.round;
    #     sprint_bead = metadata.sprint_bead, else the checked bead's metadata.sprint_bead (qa-bead.json.j2 writes none);
    #     carry_forward = checked_bead when the checked bead is a fix or finding bead (fix verification), else None (sprint review)
    #     -- carry_forward is never a metadata key; it is derived here
@dataclass(frozen=True)
class Sprint: id: str; title: str; layer: int; branch: str; target: str; depends_on: tuple[str, ...]; closed: bool; findings: int
@dataclass(frozen=True)
class Phase: root_id: str; label: str; title: str; closed: bool; sprints: tuple[Sprint, ...]; steps: tuple[Step, ...]
    step_errors: tuple[tuple[str, Error], ...]     # (bead_id, Err) for each bead step() rejected; that bead is in no step, never defaulted
@dataclass(frozen=True)
class DispatchSpec: template: str; vars: Mapping[str, Any]
@dataclass(frozen=True)
class RemoteRef: branch: str; sha: str
@dataclass(frozen=True)
class Merge: branch: str; target: str; state: Literal["clean", "conflict", "error"]; files: tuple[str, ...]; messages: tuple[str, ...]; checked_at: datetime
@dataclass(frozen=True)
class Worktree: path: str; branch: str | None; head: str
@dataclass(frozen=True)
class PullRequest: number: int; url: str; head: str; base: str; head_sha: str; ci: Literal["success", "pending", "failure", "none"]; failed_checks: tuple[str, ...]
@dataclass(frozen=True)
class GhStatus: mode: Literal["graphql", "rest", "off"]; ok: bool | None; error: Error | None; at: datetime | None; truncated: bool   # >100 open PRs
@dataclass(frozen=True)
class RepoConfig: bead_prefix: str; sanity_member: str; qa_member: str; primary_checkout: str; worktree_base: str; lint_command: str; policy_path: str; reviewers_round1: tuple[str, ...]; plans_dir: str
    # from .claude/project/atm-bd-orchestration.yaml (dev_sanity_member, qa_member, ...); the lead is Config.lead (--as)
@dataclass(frozen=True)
class Config: phase: str; lead: str; github: Literal["graphql", "rest", "off"]; interval_s: int; dry_run: bool; no_fetch: bool; repo_root: str; state_dir: str
@dataclass(frozen=True)
class DispatchContext:                                              # everything dispatch_spec needs; no hidden reads
    step: Step; sprint: Sprint; phase_id: str; phase_title: str; stack: str; lead: str; commit: str   # commit = origin/<branch> sha
    base: str; worktree_path: str; pr: PullRequest | None; layer_prs: tuple[PullRequest, ...]; repo: RepoConfig
    # checked_bead, sprint_bead, round and carry_forward come from step (never defaulted for a QA step: a missing checked_bead is Err(NotFound))

# types.py -- tick types
@dataclass(frozen=True)
class Inputs:
    now: datetime; lead: str; phase: Result[Phase]; members: Result[tuple[Member, ...]]; tasks: Result[tuple[Task, ...]]
    worktrees: Result[tuple[Worktree, ...]]; remotes: Result[tuple[RemoteRef, ...]] | None; merges: tuple[Result[Merge], ...] | None
    prs: Result[tuple[PullRequest, ...]] | None; gh: GhStatus                      # None = not read this tick (not due)
AgentStatus = Literal["busy", "stalling", "blocked", "offline", "idle"]
@dataclass(frozen=True)
class Row: task_id: str; state: Literal["running", "queued"]; kind: Literal["dev", "fix", "sprint_qa", "fix_qa", "other"]
    difficulty: Literal["hard", "normal", "fast"] | None; tag: str; marker: Literal["red", "yellow"] | None; age_s: int; description: str
@dataclass(frozen=True)
class AgentView: name: str; status: AgentStatus; status_since: datetime; depth: int; rows: tuple[Row, ...]
@dataclass(frozen=True)
class SectionRow: bead_id: str; age_s: int; reason: str; pr: int | None
@dataclass(frozen=True)
class Section: label: str; rows: tuple[SectionRow, ...]
@dataclass(frozen=True)
class StepView: bead_id: str; kind: StepKind; status: str; assignee: str | None
@dataclass(frozen=True)
class SprintView: id: str; title: str; state: Literal["closed", "in_progress", "ready", "not_ready"]; depends_on: tuple[str, ...]; steps: tuple[StepView, ...]
@dataclass(frozen=True)
class Problem: key: str; bead_id: str | None; to: str; text: str; first_seen: datetime
@dataclass(frozen=True)
class Action: at: datetime; kind: Literal["assign", "send", "batch"]; to: str; bead_ids: tuple[str, ...]; text: str; spec: DispatchSpec | None
@dataclass(frozen=True)
class PrRow: pr: PullRequest; layer: int | None; bead_id: str | None; top: bool; merge: Merge | None   # one per open phase PR, layer order
@dataclass(frozen=True)
class Metrics: done: int; total: int; pct: int; active_s: int
@dataclass(frozen=True)
class Due: fetch: bool; merges: tuple[tuple[str, str], ...]; github: bool         # what the runner reads before the next tick
# due(state: State, phase: Phase, github_mode: str, now: datetime) -> Due
# tick(inputs: Inputs, state: State, now: datetime, spec: SpecFn) -> tuple[Snapshot, tuple[Action, ...], State]   -- remote refs come from State.remotes (last read)
@dataclass(frozen=True)
class Snapshot:
    schema: int; generated_at: datetime; phase: str; root_closed: bool; stopped: Literal["closed", "idle"] | None
    agents: tuple[AgentView, ...]; sections: tuple[Section, ...]; problems: tuple[Problem, ...]; errors: tuple[Error, ...]
    metrics: Metrics; gh: GhStatus; top_pr: int | None; top_ci: str | None; mermaid: str; sprints: tuple[SprintView, ...]
    interval_s: int; lead: str; bead_prefix: str; sent: tuple[Action, ...]; prs: tuple[PrRow, ...]
    files: Mapping[str, str]   # detail-file name -> path relative to the repo root, e.g. {"prs": ".atm-bd/atm-bd-console/atm-phase-bh/prs.json"}
@dataclass(frozen=True)
class State: problems: tuple[Problem, ...]; cycle_first_send: datetime | None; last_batch: datetime | None
    last_cycle: datetime | None; idle_since: datetime | None; sent: tuple[Action, ...]; remotes: tuple[RemoteRef, ...]
    batch_due: Mapping[str, datetime]               # per recipient: next batch resend

@dataclass(frozen=True)
class PhaseFile: phase: str; root_id: str; label: str; sprints: tuple[str, ...]; depends_on: Mapping[str, tuple[str, ...]]   # .atm-bd/phase-<x>.toml + plan file

# injected functions (keep the pure tick free of imports of atm_bd and of the runner)
SpecFn = Callable[[DispatchContext], Result[DispatchSpec]]      # atm_bd.dispatch_spec (bh-4), passed to model.tick by the runner
# runner contract (implemented by bh-9, called by bh-10's app)
StepFn = Callable[[Config, "State", bool], tuple[Snapshot, "State"]]   # third arg: force_github (one GitHub read now, unless mode off)

# codec.py (the only logic in bh-1)
def to_json(obj) -> str: ...
def from_json(cls, text: str) -> Result[Any]: ...
def snapshot_stale(snapshot: Snapshot, now: datetime) -> bool: ...   # now - generated_at > 2 * interval_s; the one staleness rule (cli show, cli --once)
```

## Wire format (codec.py)
- dataclass -> JSON object with its field names; tuple -> array; Mapping -> object (string keys); None -> null; Literal -> its string (decode rejects any other value).
- datetime -> `YYYY-MM-DDTHH:MM:SSZ` UTC; decode rejects naive or non-`Z` text.
- Ok -> `{"ok": <value>}`; Err -> `{"err": <error>}`; an Error object is decoded by its `kind`.
- `from_json(cls, text)` decodes by the type annotations of `cls`; any mismatch is `Err(ParseFailed)` naming the field path; it never raises.

## Detail files (JSON schemas, written by bh-7; `<root>` = the phase root bead id)
| file | schema |
|---|---|
| snapshot.json | `Snapshot` |
| state.json | `State` |
| merge.json | `MergeFile(checked_at: datetime, merges: Mapping[str, Merge])`: the runner's cache of the last merge check per branch |
| prs.json | `PrsFile(read_at: datetime, gh: GhStatus, prs: tuple[PullRequest, ...])`: the runner's cache of the last GitHub read |
| actions.jsonl | one `ActionLine(at: datetime, kind: Literal["assign","send","batch","hold","dry_run"], to: str | None, bead: str | None, text: str)` per line |

The renderers read only `Snapshot` (PR rows, CI and merge state are in `Snapshot.prs`). Read errors live in `Snapshot.errors` and the log; there is no errors file and no CI history file.
